import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"No barrel files, and each package exports an explicit list of modules","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"No barrel files, and each package exports an explicit list of modules"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/0010-no-barrel-files"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/0010-no-barrel-files"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/adr/0010-no-barrel-files.md"}},"headers":[],"relativePath":"adr/0010-no-barrel-files.md","filePath":"adr/0010-no-barrel-files.md","lastUpdated":1794437835000}`),a={name:`adr/0010-no-barrel-files.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="no-barrel-files-and-each-package-exports-an-explicit-list-of-modules" tabindex="-1">No barrel files, and each package exports an explicit list of modules <a class="header-anchor" href="#no-barrel-files-and-each-package-exports-an-explicit-list-of-modules" aria-label="Permalink to “No barrel files, and each package exports an explicit list of modules”">​</a></h1><p>Status: accepted</p><p>A barrel is a module that re-exports another module&#39;s symbols, whether or not it also declares its own. That is the meaning Biome&#39;s rule gives the word, and the rule is the definition. We ban them across the repository with Biome&#39;s <code>noBarrelFile</code> and <code>noReExportAll</code> rules, enforced by a baseline that only shrinks, as the packet-codec check does. Consumers import the file that defines a symbol. A package lists the modules it makes public as explicit subpath entries in its <code>exports</code> map, and the <code>&quot;./*&quot;</code> patterns that expose every file are replaced.</p><p>Prismarine&#39;s barrels and its <code>&quot;./*&quot;</code> pattern go as part of the entity re-architecture. Other packages&#39; aggregating root entry points follow as separate work, one package at a time, and do not block that program.</p><p>A barrel hides which file owns a symbol, and <code>@jsprismarine/prismarine</code> exports <code>&quot;./*&quot;</code>, so every internal file is public API. Removing a class such as <code>Entity</code> is then a breaking change for anyone who imported it. This changes the convention from phase 7 of the server re-architecture plan, where Protocol&#39;s classes became importable from the package root.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};